from rdkit import Chem
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from collections import Counter

dipp='c2c(C(C)C)cccc2C(C)C'; mod='c2c(C(=C)C)cccc2C(C)C'
mols=[Chem.AddHs(Chem.MolFromSmiles(s)) for s in [f'[CH+]1N({mod})C=CN1{dipp}',f'[CH+]1N({dipp})C=CN1{dipp}']]
data=np.load('assembly.npz');xyz=data['coords'];sym=data['symbols'];pairs=[];off=0
for m in mols:
 ids=[i for i in range(m.GetNumAtoms()) if i!=29];mapping={a:off+j for j,a in enumerate(ids)}
 for b in m.GetBonds():
  i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
  if 29 in (i,j):continue
  pairs.append((mapping[i],mapping[j]))
 off+=len(ids)
ir=off;zn=off+1;hyd=off+2
pairs.extend([(ir,0),(ir,63),(ir,4),(ir,5),(ir,zn),(ir,hyd),(zn,off+3),(off+3,off+4),(off+3,off+5),(off+3,off+6)]+[(off+4,off+i) for i in [7,8,9]])
print('Composition',Counter(sym))
for j in [0,63,4,5,zn,hyd]:print('Ir-',j,sym[j],np.linalg.norm(xyz[ir]-xyz[j]))
print('Zn-C',np.linalg.norm(xyz[zn]-xyz[off+3]))
for i,j in pairs:
 r=np.linalg.norm(xyz[i]-xyz[j]);
 if sym[i] in ['C','N'] and sym[j] in ['C','N'] and (r<1.2 or r>1.65):print('unusual organic bond',i,j,r)
# Only non-neighbors separated by >= three bonds are screened as contacts.
graph={i:set() for i in range(len(xyz))}
for i,j in pairs:graph[i].add(j);graph[j].add(i)
cl=[]
for i in range(len(xyz)):
 excluded={i}|graph[i]
 for j in graph[i]: excluded|=graph[j]
 for j in range(i+1,len(xyz)):
  if j in excluded:continue
  r=np.linalg.norm(xyz[i]-xyz[j]); limit=1.35 if 'H' in [sym[i],sym[j]] else 2.0
  if r<limit:cl.append((i,j,sym[i],sym[j],r))
print('Close nonbonded',cl)
colors={'H':'#ededed','C':'#444444','N':'#245df7','Ir':'#cc8733','Zn':'#9b67ac'}
sizes={'H':18,'C':65,'N':75,'Ir':160,'Zn':140}
fig=plt.figure(figsize=(13,7))
# molecular y is upward, and +z is toward the page viewer.
p=xyz[:,[0,2,1]]*np.array([1,-1,1])
for panel,(el,az) in enumerate([(15,-80),(20,-35)]):
 ax=fig.add_subplot(1,2,panel+1,projection='3d')
 for i,j in pairs:
  ax.plot(*p[[i,j]].T,color='#777777',linewidth=1.2,alpha=.95)
 for s in colors:
  ids=np.where(sym==s)[0];ax.scatter(*p[ids].T,c=colors[s],s=sizes[s],edgecolors='#222222',linewidths=.3,depthshade=True)
 for ix in [ir,zn,hyd,0,63,4,5]:ax.text(*p[ix],f'{sym[ix]}{ix}',fontsize=8,color='red')
 ax.view_init(el,az);ax.set_box_aspect([1,1,1]);ax.set_axis_off()
 mid=(p.max(0)+p.min(0))/2;r=np.max(np.ptp(p,axis=0))/2+.3
 ax.set_xlim(mid[0]-r,mid[0]+r);ax.set_ylim(mid[1]-r,mid[1]+r);ax.set_zlim(mid[2]-r,mid[2]+r)
plt.tight_layout();plt.savefig('structure.png',dpi=150)
